import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  updateDoc,
  onSnapshot,
  arrayUnion 
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  BookOpen, 
  Plus, 
  X, 
  ChevronRight, 
  Play, 
  Pause, 
  Volume2, 
  VolumeX, 
  Maximize, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  Layers, 
  Eye, 
  CheckCircle, 
  Copy, 
  Edit, 
  GraduationCap, 
  FileUp, 
  FileDown,
  Lock,
  FileText,
  Award,
  File,
  FileImage,
  FileSpreadsheet,
  CloudUpload,
  Download,
  Database,
  AlertTriangle,
  ClipboardCheck,
  ListChecks,
  PlusCircle,
  Search,
  Library,
  PencilLine,
  Star,
  Quote,
  ShieldAlert,
  MessageSquareHeart,
  User as UserIcon,
  MessageCircle,
  Globe,
  Info,
  UserCheck,
  Clapperboard,
  ChevronLeft
} from 'lucide-react';

// Constante de Armazenamento Máximo (5GB)
const MAX_STORAGE = 5 * 1024 * 1024 * 1024;

interface MaterialFile {
  id: string;
  name: string;
  type: string;
  size: string;
  sizeBytes: number;
  date: Date;
  url: string;
}

interface Question {
  id: string;
  text: string;
  options: string[];
  correctOptionIndex: number;
}

interface Exam {
  id: string;
  title: string;
  courseId: string;
  courseName: string;
  passingGrade: number;
  questions: Question[];
  type: 'evaluation' | 'activity';
  linkedLessonId?: string;
  linkedModuleId?: string;
}

interface Feedback {
  id: string;
  studentName: string;
  courseName: string;
  rating: number;
  date: Date;
  text: string;
  type: 'praise' | 'criticism' | 'suggestion';
  criteria: {
    didactics: number;
    support: number;
    material: number;
  };
}

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  setActiveSub: (view: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, setActiveSub }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});
  const [allModulesGrouped, setAllModulesGrouped] = useState<Record<string, { course: Course, modules: Module[] }>>({});
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  // Real-time Exams State
  const [exams, setExams] = useState<Exam[]>([]);

  // State para Materiais
  const [materials, setMaterials] = useState<MaterialFile[]>(() => {
    const saved = sessionStorage.getItem('eb_materials_mock');
    return saved ? JSON.parse(saved).map((m: any) => ({...m, date: new Date(m.date)})) : [];
  });

  // State para o Material Picker
  const [isMaterialPickerOpen, setIsMaterialPickerOpen] = useState(false);
  const [pickerMode, setPickerMode] = useState<'image' | 'document'>('document');
  const [pickerCallback, setPickerCallback] = useState<(url: string) => void>(() => {});

  // State para Avaliações (Exams)
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isEditingExam, setIsEditingExam] = useState(false);
  const [examForm, setExamForm] = useState<{
    id?: string;
    title: string;
    courseId: string;
    passingGrade: number;
    questions: Question[];
    type: 'evaluation' | 'activity';
    linkedLessonId?: string;
    linkedModuleId?: string;
  }>({
    title: '',
    courseId: '',
    passingGrade: 7.0,
    questions: [{ id: '1', text: '', options: ['', '', '', ''], correctOptionIndex: 0 }],
    type: 'activity'
  });

  // State para Feedbacks (Mural de Voz)
  const [feedbacks] = useState<Feedback[]>([
    {
      id: '1',
      studentName: 'Lucas Oliveira',
      courseName: 'Teologia Sistemática I',
      rating: 5,
      date: new Date('2024-03-20'),
      text: 'O professor tem uma didática excelente! Os materiais de apoio são muito ricos e ajudam muito na fixação.',
      type: 'praise',
      criteria: { didactics: 5, support: 5, material: 5 }
    },
    {
      id: '2',
      studentName: 'Ana Clara Souza',
      courseName: 'História do Cristianismo',
      rating: 4,
      date: new Date('2024-03-18'),
      text: 'Gostaria de sugerir mais aulas ao vivo para tirarmos dúvidas em tempo real.',
      type: 'suggestion',
      criteria: { didactics: 4, support: 3, material: 5 }
    }
  ]);

  const materialInputRef = useRef<HTMLInputElement>(null);

  // UX Emoção: States de Fluxo
  const [showIntegrityModal, setShowIntegrityModal] = useState(false);
  const [pendingExam, setPendingExam] = useState<Exam | null>(null);
  const [showCertificateScreen, setShowCertificateScreen] = useState(false);

  // MOTOR DE EXECUÇÃO DE PROVA (NOVO)
  const [isExamStarted, setIsExamStarted] = useState(false);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [userAnswers, setUserAnswers] = useState<Record<string, number>>({});
  const [examFinished, setExamFinished] = useState(false);
  const [lastExamScore, setLastExamScore] = useState<number | null>(null);

  // Lógica de Tentativas (Business Logic)
  const [userExamAttempts, setUserExamAttempts] = useState<Record<string, number>>(() => {
    const saved = localStorage.getItem(`eb_attempts_${user.uid}`);
    return saved ? JSON.parse(saved) : {};
  });

  useEffect(() => {
    localStorage.setItem(`eb_attempts_${user.uid}`, JSON.stringify(userExamAttempts));
  }, [userExamAttempts, user.uid]);

  // Sincronização em tempo real das Avaliações
  useEffect(() => {
    const q = query(collection(db, 'exams'), orderBy('title', 'asc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const fetchedExams: Exam[] = [];
      snapshot.forEach((doc) => {
        fetchedExams.push({ id: doc.id, ...doc.data() } as Exam);
      });
      setExams(fetchedExams);
    });
    return () => unsubscribe();
  }, []);

  // Persistência simulada de materiais
  useEffect(() => {
    sessionStorage.setItem('eb_materials_mock', JSON.stringify(materials));
  }, [materials]);

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [activeModalTab, setActiveModalTab] = useState<'geral' | 'docente' | 'midia'>('geral');
  const [isEditingCourse, setIsEditingCourse] = useState(false);
  const [editingCourseId, setEditingCourseId] = useState<string | null>(null);

  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false); 
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [isEditingLesson, setIsEditingLesson] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);
  const [currentEditingModule, setCurrentEditingModule] = useState<Module | null>(null); 
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [previewExam, setPreviewExam] = useState<Exam | null>(null); 
  const [isConcluded, setIsConcluded] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [timeLeft, setTimeLeft] = useState(300);
  const timerIntervalRef = useRef<number | null>(null);
  const [showWelcomeModal, setShowWelcomeModal] = useState(false);
  const [showCompletionModal, setShowCompletionModal] = useState(false);

  const [isStudentSimulationMode, setIsStudentSimulationMode] = useState(false);
  const [isCertificateUnlocked, setIsCertificateUnlocked] = useState(false);
  const [completedLessonIds, setCompletedLessonIds] = useState<Set<string>>(new Set());
  const [totalLessons, setTotalLessons] = useState(0);

  const [playerVolume, setPlayerVolume] = useState(80); 
  const [isMuted, setIsMuted] = useState(false); 
  const iframeRef = useRef<HTMLIFrameElement>(null); 
  const playerContainerRef = useRef<HTMLDivElement>(null); 

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '', tema: '', categoria: 'Teologia',
    nivelDificuldade: 'Iniciante' as 'Iniciante' | 'Intermediário' | 'Avançado',
    professorResponsavel: user.displayName || '',
    professorBio: '',
    professorPhotoURL: '',
    descricaoLonga: '', capaUrl: '', cargaHoraria: '',
    materialGlobalUrl: '', publicoAlvo: 'Geral' as const, geraCertificado: false
  });
  const [moduleForm, setModuleForm] = useState({ nome: '', courseId: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '', descricao: '', videoUrl: '', materialUrl: ''
  });

  // --- Funções de Dados ---
  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModulesForCourse = async (courseId: string) => {
    const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
    const querySnapshot = await getDocs(q);
    const fetched: Module[] = [];
    querySnapshot.forEach((doc) => {
      fetched.push({ id: doc.id, ...doc.data(), courseId } as Module);
    });
    return fetched;
  };

  const fetchAllModulesGrouped = async () => {
    setLoading(true);
    try {
      const grouped: Record<string, { course: Course, modules: Module[] }> = {};
      for (const course of myCourses) {
        const mods = await fetchModulesForCourse(course.id);
        for (const mod of mods) {
          await fetchLessons(course.id, mod.id);
        }
        grouped[course.id] = { course, modules: mods };
      }
      setAllModulesGrouped(grouped);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error(error);
    }
  };

  const fetchCompletedLessons = useCallback(async (studentId: string, courseId: string) => {
    if (!studentId || !courseId) return new Set<string>();
    try {
      const key = `completed_lessons_sim_${studentId}_${courseId}`;
      const stored = localStorage.getItem(key);
      return new Set(stored ? JSON.parse(stored) : []);
    } catch (error) {
      console.error(error);
    }
    return new Set<string>();
  }, []);

  const updateCompletedLesson = useCallback(async (studentId: string, lessonId: string) => {
    if (!studentId || !lessonId) return;
    try {
      const key = `completed_lessons_sim_${studentId}_${selectedCourse?.id}`;
      const currentCompleted = await fetchCompletedLessons(studentId, selectedCourse?.id || '');
      if (!currentCompleted.has(lessonId)) {
        currentCompleted.add(lessonId);
        localStorage.setItem(key, JSON.stringify(Array.from(currentCompleted)));
        setCompletedLessonIds(currentCompleted);
      }
    } catch (error) {
      console.error(error);
    }
  }, [fetchCompletedLessons, selectedCourse?.id]);

  // --- Effects ---
  useEffect(() => { fetchMyCourses(); }, [user.uid]);

  useEffect(() => {
    if (activeSub === 'modulos') { fetchAllModulesGrouped(); }
  }, [activeSub, myCourses]);

  useEffect(() => {
    if (selectedCourse && modules.length > 0) {
      let count = 0;
      for (const mod of modules) { count += (lessonsByModule[mod.id]?.length || 0); }
      setTotalLessons(count);
    } else { setTotalLessons(0); }
  }, [selectedCourse, modules, lessonsByModule]);

  useEffect(() => {
    const shouldStartTimer = isStudentSimulationMode && previewLesson && !showWelcomeModal && isPlaying;
    if (shouldStartTimer && timeLeft > 0) {
      if (!timerIntervalRef.current) {
        timerIntervalRef.current = window.setInterval(async () => {
          setTimeLeft(prevTime => {
            if (prevTime <= 1) {
              if (timerIntervalRef.current) { clearInterval(timerIntervalRef.current); timerIntervalRef.current = null; }
              setIsConcluded(true);
              if (user.uid && previewLesson?.id) { updateCompletedLesson(user.uid, previewLesson.id); }
              if (!showCompletionModal) { setShowCompletionModal(true); }
              return 0;
            }
            return prevTime - 1;
          });
        }, 1000);
      }
    } else if (timerIntervalRef.current) {
      clearInterval(timerIntervalRef.current);
      timerIntervalRef.current = null;
    }
    return () => { if (timerIntervalRef.current) { clearInterval(timerIntervalRef.current); timerIntervalRef.current = null; } };
  }, [previewLesson, isStudentSimulationMode, showWelcomeModal, isPlaying, timeLeft, showCompletionModal, user.uid, previewLesson?.id, updateCompletedLesson]);

  useEffect(() => {
    if (selectedCourse?.geraCertificado && isStudentSimulationMode && totalLessons > 0) {
      setIsCertificateUnlocked(completedLessonIds.size >= totalLessons);
    } else { setIsCertificateUnlocked(false); }
  }, [selectedCourse?.geraCertificado, isStudentSimulationMode, completedLessonIds, totalLessons]);

  useEffect(() => {
    if (selectedCourse && user.uid) { fetchCompletedLessons(user.uid, selectedCourse.id).then(setCompletedLessonIds); }
    else { setCompletedLessonIds(new Set()); }
  }, [selectedCourse, user.uid, fetchCompletedLessons]);

  const getYouTubeVideoId = (url: string) => {
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    return ytMatch && ytMatch[1];
  };

  const sendPlayerCommand = useCallback((command: string, args: any = '') => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(JSON.stringify({ event: 'command', func: command, args: args }), '*');
    }
  }, []);

  const togglePlay = () => {
    if (isPlaying) { sendPlayerCommand('pauseVideo'); setIsPlaying(false); }
    else { sendPlayerCommand('playVideo'); setIsPlaying(true); setShowWelcomeModal(false); }
  };

  const toggleMute = () => {
    if (isMuted) { sendPlayerCommand('unMute'); } else { sendPlayerCommand('mute'); }
    setIsMuted(prev => !prev);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (vol === 0) { if (!isMuted) sendPlayerCommand('mute'); setIsMuted(true); }
    else { if (isMuted) sendPlayerCommand('unMute'); sendPlayerCommand('setVolume', [vol]); setIsMuted(false); }
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) playerContainerRef.current.requestFullscreen();
      else document.exitFullscreen();
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { alert("A imagem de capa não pode exceder 5 MB."); e.target.value = ''; return; }
    const reader = new FileReader();
    reader.onloadend = () => { setCourseForm(prev => ({ ...prev, capaUrl: reader.result as string })); };
    reader.readAsDataURL(file);
  };

  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);
      if (isEditingCourse && editingCourseId) {
        const courseRef = doc(db, 'cursos', editingCourseId);
        await updateDoc(courseRef, { ...courseForm });
        if (selectedCourse?.id === editingCourseId) { setSelectedCourse({ ...selectedCourse, ...courseForm }); }
      } else {
        await addDoc(collection(db, 'cursos'), { 
          ...courseForm, 
          professorId: user.uid, 
          inscritos: 0, 
          status: 'rascunho', 
          createdAt: serverTimestamp() 
        });
      }
      handleCloseCourseModal();
      await fetchMyCourses();
    } catch (error) {
      console.error(error);
    } finally { setLoading(false); }
  };

  const handleEditCourseInfo = (course: Course) => {
    setCourseForm({
      nome: course.nome, 
      tema: course.tema || '', 
      categoria: course.categoria || 'Teologia',
      nivelDificuldade: course.nivelDificuldade || 'Iniciante',
      professorResponsavel: course.professorResponsavel || '',
      professorBio: course.professorBio || '',
      professorPhotoURL: course.professorPhotoURL || '',
      descricaoLonga: course.descricaoLonga || '', 
      capaUrl: course.capaUrl || '',
      cargaHoraria: course.cargaHoraria, 
      materialGlobalUrl: course.materialGlobalUrl || '',
      publicoAlvo: course.publicoAlvo,
      geraCertificado: course.geraCertificado || false
    });
    setEditingCourseId(course.id);
    setIsEditingCourse(true);
    setShowCourseModal(true);
    setActiveModalTab('geral');
    setOpenMenuId(null);
  };

  const handleCloseCourseModal = () => {
    setShowCourseModal(false);
    setIsEditingCourse(false);
    setEditingCourseId(null);
    setCourseForm({
      nome: '', tema: '', categoria: 'Teologia', nivelDificuldade: 'Iniciante',
      professorResponsavel: user.displayName || '', professorBio: '', professorPhotoURL: '',
      descricaoLonga: '', capaUrl: '', cargaHoraria: '', materialGlobalUrl: '',
      publicoAlvo: 'Geral', geraCertificado: false
    });
    setActiveModalTab('geral');
  };

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm("Tem certeza que deseja excluir o curso inteiro?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId));
      setMyCourses(prev => prev.filter(c => c.id !== courseId));
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDuplicateCourse = async (course: Course) => {
    try {
      const { id, ...data } = course;
      await addDoc(collection(db, 'cursos'), { ...data, nome: `${data.nome} (Cópia)`, createdAt: serverTimestamp() });
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDeleteModule = async (courseId: string, moduleId: string) => {
    if (!confirm("Excluir este módulo e todo seu conteúdo?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId, 'modulos', moduleId));
      if (selectedCourse) { setModules(prev => prev.filter(m => m.id !== moduleId)); }
      fetchAllModulesGrouped();
    } catch (error) { console.error(error); }
  };

  const handleSaveModule = async (e: React.FormEvent) => {
    e.preventDefault();
    const finalCourseId = selectedCourse?.id || moduleForm.courseId;
    if (!finalCourseId) { alert("Selecione um curso."); return; }
    try {
      if (currentEditingModule) {
        const modRef = doc(db, 'cursos', currentEditingModule.courseId, 'modulos', currentEditingModule.id);
        await updateDoc(modRef, { nome: moduleForm.nome });
      } else {
        const qOrder = query(collection(db, 'cursos', finalCourseId, 'modulos'));
        const snapOrder = await getDocs(qOrder);
        const nextOrder = snapOrder.size + 1;
        await addDoc(collection(db, 'cursos', finalCourseId, 'modulos'), { 
          nome: moduleForm.nome, 
          ordem: nextOrder, 
          createdAt: serverTimestamp() 
        });
      }
      setIsModuleModalOpen(false);
      setModuleForm({ nome: '', courseId: '' });
      setCurrentEditingModule(null);
      if (selectedCourse) {
         const mods = await fetchModulesForCourse(selectedCourse.id);
         setModules(mods);
      }
      fetchAllModulesGrouped();
    } catch (error) { console.error(error); }
  };

  const handleOpenCreateModule = () => {
    setModuleForm({ nome: '', courseId: selectedCourse?.id || '' });
    setCurrentEditingModule(null);
    setIsModuleModalOpen(true);
  };

  const handleEditModule = (mod: Module) => {
    setCurrentEditingModule(mod);
    setModuleForm({ nome: mod.nome, courseId: mod.courseId });
    setIsModuleModalOpen(true);
  };

  const handleSaveLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;
    const allLessonsFlattened = Object.values(lessonsByModule).flat() as Lesson[];
    const arquivoJaUsado = allLessonsFlattened.find(l => 
        l.materialUrl === lessonForm.materialUrl && 
        l.materialUrl !== '' && 
        l.id !== editingLessonId
    );
    if (arquivoJaUsado) {
        alert(`Atenção: O arquivo selecionado já está vinculado à aula "${arquivoJaUsado.titulo}". Por favor, escolha outro arquivo.`);
        return;
    }
    try {
      if (isEditingLesson && editingLessonId) {
        const lessonRef = doc(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas', editingLessonId);
        await updateDoc(lessonRef, { ...lessonForm });
      } else {
        await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), { ...lessonForm, ordem: (lessonsByModule[activeModuleId]?.length || 0) + 1, createdAt: serverTimestamp() });
      }
      setShowLessonModal(false);
      setIsEditingLesson(false);
      setEditingLessonId(null);
      setLessonForm({ titulo: '', descricao: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);
    } catch (error) { console.error(error); }
  };

  const handleDeleteLesson = async (moduleId: string, lessonId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Tem certeza que deseja DESTRUIR esta aula permanentemente?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas', lessonId));
      fetchLessons(selectedCourse.id, moduleId);
      if (previewLesson?.id === lessonId) setPreviewLesson(null);
    } catch (error) { console.error(error); }
  };

  const handleEditLesson = (lesson: Lesson, moduleId: string) => {
    setActiveModuleId(moduleId);
    setLessonForm({ titulo: lesson.titulo, descricao: lesson.descricao || '', videoUrl: lesson.videoUrl, materialUrl: lesson.materialUrl });
    setEditingLessonId(lesson.id);
    setIsEditingLesson(true);
    setShowLessonModal(true);
  };

  const openCourseDetail = async (course: Course) => {
    setSelectedCourse(course);
    const mods = await fetchModulesForCourse(course.id);
    setModules(mods);
    for (const mod of mods) { fetchLessons(course.id, mod.id); }
  };

  const openPreview = (lesson: Lesson, moduleId: string, studentMode: boolean) => {
    setActiveModuleId(moduleId);
    setPreviewLesson(lesson);
    setPreviewExam(null); 
    setIsExamStarted(false);
    setShowCertificateScreen(false);
    setIsPlaying(false);
    setTimeLeft(300);
    setIsConcluded(false);
    setIsMuted(false);
    setPlayerVolume(80);
    sendPlayerCommand('setVolume', [80]);
    sendPlayerCommand('unMute');
    setIsStudentSimulationMode(studentMode);
    setShowWelcomeModal(studentMode);
    setShowCompletionModal(false);
  };

  // Business Logic: Validação de Tentativas
  const getExamAttemptInfo = (exam: Exam) => {
    const current = userExamAttempts[exam.id] || 0;
    const limit = exam.type === 'evaluation' ? 1 : 3;
    return { current, limit, isBlocked: current >= limit };
