      alert(`Atenção: Você já utilizou seu limite de ${limit} ${limit === 1 ? 'tentativa única' : 'tentativas'} para esta atividade.`);
      return;
    }
    if (exam.type === 'evaluation' && studentMode) {
      setPendingExam(exam);
      setShowIntegrityModal(true);
      return;
    }
    setPreviewExam(exam);
    setPreviewLesson(null); 
    setIsExamStarted(false);
    setExamFinished(false);
    setCurrentQuestionIndex(0);
    setUserAnswers({});
    setShowCertificateScreen(false);
    setIsStudentSimulationMode(studentMode);
    setShowWelcomeModal(false);
    setShowCompletionModal(false);
    setIsPlaying(false);
  };

  // NOVO MOTOR: Iniciar Prova
  const handleStartExamActual = () => {
    setIsExamStarted(true);
    setCurrentQuestionIndex(0);
    setUserAnswers({});
    setExamFinished(false);
  };

  // NOVO MOTOR: Selecionar Resposta
  const handleSelectAnswer = (questionId: string, optionIndex: number) => {
    setUserAnswers(prev => ({ ...prev, [questionId]: optionIndex }));
  };

  // NOVO MOTOR: Finalizar e Persistir Resultado
  const handleFinishExam = async (exam: Exam) => {
    // Cálculo de Nota (0-10)
    let correctCount = 0;
    exam.questions.forEach((q) => {
      if (userAnswers[q.id] === q.correctOptionIndex) {
        correctCount++;
      }
    });

    const score = (correctCount / exam.questions.length) * 10;
    const status = score >= exam.passingGrade ? 'Aprovado' : 'Reprovado';

    try {
      // 1. Salvar no Firestore (Histórico Real para o Diário)
      await addDoc(collection(db, 'exam_results'), {
        studentId: user.uid,
        studentName: user.displayName,
        examId: exam.id,
        courseId: exam.courseId,
        score: score,
        status: status,
        timestamp: serverTimestamp(),
        type: exam.type
      });

      // 2. Atualizar Tentativas Locais (Simulação)
      setUserExamAttempts(prev => ({
        ...prev,
        [exam.id]: (prev[exam.id] || 0) + 1
      }));

      setLastExamScore(score);
      setExamFinished(true);
      setIsExamStarted(false);
    } catch (error) {
      console.error("Erro ao salvar resultado:", error);
      alert("Houve um erro técnico ao processar sua prova. Tente novamente.");
    }
