  // --- Lógica de Materiais ---
  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const currentUsedStorage = materials.reduce((acc, m) => acc + m.sizeBytes, 0);
  const storagePercentage = (currentUsedStorage / MAX_STORAGE) * 100;

  const handleMaterialUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    let tempUsed = currentUsedStorage;
    const newMaterials: MaterialFile[] = [];
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      if (tempUsed + file.size > MAX_STORAGE) {
        alert(`Espaço insuficiente para o arquivo "${file.name}".`);
        continue;
      }
      tempUsed += file.size;
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      const blobUrl = URL.createObjectURL(file);
      newMaterials.push({
        id: Math.random().toString(36).substr(2, 9),
        name: file.name, type: extension, size: formatFileSize(file.size),
        sizeBytes: file.size, date: new Date(), url: blobUrl
      });
    }
    setMaterials(prev => [...newMaterials, ...prev]);
  };

  const handleDeleteMaterial = (id: string) => {
    const file = materials.find(m => m.id === id);
    if (!file) return;
    if (confirm(`Excluir "${file.name}"?`)) {
