                            const linkedActivity = exams.find(e => e.linkedLessonId === lesson.id && e.type === 'activity');
                            return (
                              <React.Fragment key={lesson.id}>
                                <button onClick={() => openPreview(lesson, mod.id, isStudentSimulationMode)} className={`flex items-center justify-between w-full p-3 rounded-xl transition-all ${isCurrent ? 'bg-indigo-600 text-white shadow-md' : 'bg-gray-700/50 text-gray-300 hover:bg-gray-600'}`}>
