                                </button>
                                {linkedActivity && (
                                  <button onClick={() => openExamPreview(linkedActivity, isStudentSimulationMode)} className={`flex items-center gap-3 w-[calc(100%-1rem)] ml-4 p-2.5 rounded-xl border transition-all ${previewExam?.id === linkedActivity.id ? 'bg-blue-600 text-white' : 'bg-blue-900/10 border-blue-900/20 text-blue-400 hover:bg-blue-900/20'}`}>
                                    <PencilLine size={14} /><span className="text-[10px] font-black uppercase truncate">Atividade: {linkedActivity.title}</span>
                                  </button>
                                )}
                              </React.Fragment>
                            );
                          })}
                          {moduleEval && (
                            <button onClick={() => openExamPreview(moduleEval, isStudentSimulationMode)} className={`flex items-center gap-3 w-full p-3 rounded-xl border transition-all ${previewExam?.id === moduleEval.id ? 'bg-orange-600 text-white shadow-xl' : 'bg-orange-500/10 border-orange-500/20 text-orange-400 hover:bg-orange-500/20'}`}>
                              <Star size={14} /><span className="text-[10px] font-black uppercase truncate">Avaliação Final do Módulo</span>
                            </button>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          </div>
          {showIntegrityModal && (
            <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 bg-slate-950/95 backdrop-blur-xl animate-in fade-in duration-500">
