            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'feedback') {
      return (
        <div className="space-y-8 animate-in fade-in duration-500">
          <header><h1 className="text-2xl font-bold text-slate-900">Dashboard de Reputação</h1><p className="text-slate-500 text-sm">Monitoramento de qualidade e satisfação.</p></header>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="bg-slate-900 p-8 rounded-[2rem] border border-slate-800 shadow-xl flex flex-col justify-center items-center text-center space-y-4">
              <div className="p-4 bg-indigo-600/10 text-indigo-400 rounded-3xl"><Star size={40} fill="currentColor" className="text-amber-400" /></div>
              <div><h3 className="text-4xl font-black text-white">4.8</h3><p className="text-slate-400 text-xs uppercase font-bold tracking-widest">Nota Geral</p></div>
            </div>
