    if (activeSub === 'avaliacao') {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4">
            <div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Gestão de Avaliações</h1><p className="text-slate-500 text-sm">Criação de provas e testes.</p></div>
