                  <div className="flex items-center gap-2 mb-4">
                    <p className="text-indigo-400 text-[10px] font-black uppercase tracking-widest">{exam.courseName}</p>
                    <span className="w-1 h-1 bg-slate-700 rounded-full" />
                    <span className={`text-[9px] font-black uppercase tracking-tighter ${exam.type === 'evaluation' ? 'text-orange-400' : 'text-blue-400'}`}>
