          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {materials.map((file) => (
              <div key={file.id} className="group relative bg-slate-900 rounded-3xl border border-slate-800 p-5 shadow-xl hover:border-indigo-500/40 transition-all">
