          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {allModules.map((mod: any) => (<div key={mod.id} className="group bg-slate-900 rounded-3xl border border-slate-800 p-6 shadow-xl hover:border-indigo-500/50 transition-all"><h3 className="text-white font-bold text-lg mb-2">{mod.ordem}. {mod.nome}</h3><span className="text-indigo-400 text-[10px] font-black uppercase">{mod.courseName}</span></div>))}
          </div>
        </div>
      );
    }

    if (activeSub === 'cursos' && selectedCourse) {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex items-center justify-between gap-4"><div className="flex items-center gap-4"><button onClick={() => setSelectedCourse(null)} className="h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button><div><h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1><p className="text-slate-500 text-sm">{selectedCourse.tema}</p></div></div><button onClick={handleOpenCreateModule} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Módulo</button></header>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 space-y-4"><div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-4 space-y-4">{modules.map((mod) => (<div key={mod.id} className="border border-slate-100 rounded-xl group bg-slate-50/20 overflow-hidden"><div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white"><h3 className="font-bold text-slate-800 text-sm">Módulo {mod.ordem}: {mod.nome}</h3><button onClick={() => { setActiveModuleId(mod.id); setIsEditingLesson(false); setEditingLessonId(null); setShowLessonModal(true); }} className="p-1.5 text-indigo-600 bg-indigo-50 rounded-lg"><Plus size={18} /></button></div><div className="p-2 space-y-1">{lessonsByModule[mod.id]?.map((lesson) => (<div key={lesson.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-white transition-all"><span>{lesson.titulo}</span><button onClick={() => openPreview(lesson, mod.id, false)} className="p-1.5 text-indigo-600"><Eye size={16} /></button></div>))}</div></div>))}</div></div>
          </div>
        </div>
      );
    }

    return (
      <div className="space-y-6 animate-in fade-in duration-500"><header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Portal do Professor</h1><p className="text-slate-500 text-sm">Gestão de cursos EAD.</p></div><button onClick={() => { setIsEditingCourse(false); setEditingCourseId(null); setCourseForm({ nome: '', tema: '', categoria: 'Teologia', nivelDificuldade: 'Iniciante', professorResponsavel: user.displayName || '', professorBio: '', professorPhotoURL: '', descricaoLonga: '', capaUrl: '', cargaHoraria: '', materialGlobalUrl: '', publicoAlvo: 'Geral', geraCertificado: false }); setShowCourseModal(true); setActiveModalTab('geral'); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg shadow-indigo-100"><Plus size={18} /> Novo Curso</button></header><div className="grid grid-cols-1 md:grid-cols-3 xl:grid-cols-6 gap-4">{loading ? (<div className="col-span-full py-20 flex justify-center"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div></div>) : myCourses.map(course => (<div key={course.id} onClick={() => openCourseDetail(course)} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-xl hover:border-indigo-200 group cursor-pointer flex flex-col relative"><div className="h-24 overflow-hidden bg-slate-100 relative">{course.capaUrl ? <img src={course.capaUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform" /> : <div className="h-full flex items-center justify-center text-slate-200"><BookOpen size={32} /></div>}</div><div className="p-3 flex-1"><h3 className="font-bold text-slate-900 text-xs mb-1 leading-tight">{course.nome}</h3></div></div>))}</div></div>
    );
  };

  const renderMaterialPicker = () => {
    if (!isMaterialPickerOpen) return null;
    const filteredMaterials = materials.filter(m => {
      const isImg = ['jpg', 'jpeg', 'png', 'webp', 'gif'].includes(m.type.toLowerCase());
      return pickerMode === 'image' ? isImg : !isImg;
    });
    return (
      <div className="fixed inset-0 z-[10000] flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-md animate-in fade-in duration-300">
        <div className="bg-slate-900 w-full max-w-5xl h-[80vh] rounded-[2.5rem] shadow-2xl border border-slate-800 flex flex-col overflow-hidden">
          <header className="px-8 py-6 border-b border-slate-800 flex items-center justify-between"><h2 className="text-xl font-bold text-white">Selecionar da Biblioteca</h2><button onClick={() => setIsMaterialPickerOpen(false)} className="text-slate-400 hover:text-white transition-colors"><X size={28} /></button></header>
          <div className="flex-1 overflow-y-auto p-8 grid grid-cols-2 md:grid-cols-4 gap-6">
            {filteredMaterials.map((file) => (
              <div key={file.id} onClick={() => handleSelectMaterialFromPicker(file)} className="group bg-slate-800/40 rounded-3xl border border-slate-700/50 p-4 hover:border-indigo-500 hover:bg-slate-800 transition-all cursor-pointer">
                <div className="aspect-square bg-slate-900 rounded-2xl mb-4 flex items-center justify-center overflow-hidden">{pickerMode === 'image' ? <img src={file.url} className="w-full h-full object-cover" /> : getFileIcon(file.type)}</div>
                <h4 className="text-white text-xs font-bold truncate">{file.name}</h4>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="relative">
      {renderMainContent()}
      {renderMaterialPicker()}

      {/* MODAL GLOBAL: CONSTRUTOR DE AVALIAÇÃO - FIREBASE READY */}
      {isExamModalOpen && (
        <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-slate-900 w-full max-w-4xl max-h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col border border-slate-800 animate-in zoom-in-95">
            <header className="px-8 py-6 border-b border-slate-800 flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className={`p-3 rounded-2xl ${examForm.type === 'evaluation' ? 'bg-orange-600 shadow-orange-600/20' : 'bg-blue-600 shadow-blue-600/20 shadow-xl'}`}>{examForm.type === 'evaluation' ? <Star size={24} /> : <PencilLine size={24} />}</div>
                <div><h2 className="text-xl font-bold text-white">{isEditingExam ? 'Editar Avaliação' : 'Nova Avaliação'}</h2></div>
              </div>
              <button onClick={() => setIsExamModalOpen(false)} className="text-slate-500 hover:text-white transition-colors"><X size={24} /></button>
            </header>
            <form onSubmit={handleSaveExam} className="flex-1 overflow-y-auto p-8 space-y-8">
              <div className="grid grid-cols-2 gap-6 p-4 bg-slate-800/20 rounded-3xl border border-slate-800">
                <button type="button" onClick={() => setExamForm(prev => ({...prev, type: 'activity'}))} className={`p-6 rounded-2xl border transition-all ${examForm.type === 'activity' ? 'bg-blue-600/10 border-blue-500 text-blue-400' : 'border-slate-800 text-slate-500 hover:bg-slate-800'}`}><PencilLine size={32} className="mx-auto mb-2" /><span className="font-bold text-xs uppercase tracking-widest">Atividade de Fixação</span></button>
                <button type="button" onClick={() => setExamForm(prev => ({...prev, type: 'evaluation'}))} className={`p-6 rounded-2xl border transition-all ${examForm.type === 'evaluation' ? 'bg-orange-600/10 border-orange-500 text-orange-400' : 'border-slate-800 text-slate-500 hover:bg-slate-800'}`}><Star size={32} className="mx-auto mb-2" /><span className="font-bold text-xs uppercase tracking-widest">Avaliação Oficial</span></button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
                <div className="md:col-span-7 space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Título da Prova</label><input required value={examForm.title} onChange={e => setExamForm({...examForm, title: e.target.value})} placeholder="Ex: Prova Mensal" className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                <div className="md:col-span-3 space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Curso Alvo</label><select required value={examForm.courseId} onChange={e => setExamForm({...examForm, courseId: e.target.value})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none"><option value="">Selecione...</option>{myCourses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
                <div className="md:col-span-2 space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Nota Mínima</label><input type="number" step="0.1" value={examForm.passingGrade} onChange={e => setExamForm({...examForm, passingGrade: parseFloat(e.target.value)})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none" /></div>
              </div>
              <div className="space-y-6">
                <div className="flex items-center justify-between border-b border-slate-800 pb-4"><h3 className="font-black text-indigo-400 text-xs uppercase tracking-[0.3em]">Questões</h3><button type="button" onClick={handleAddQuestion} className="flex items-center gap-2 text-indigo-400 hover:text-indigo-300 transition-colors font-bold text-xs uppercase"><Plus size={16} /> Adicionar Pergunta</button></div>
                <div className="space-y-8">{examForm.questions.map((q, qIndex) => (<div key={qIndex} className="bg-slate-800/40 p-6 rounded-3xl border border-slate-700/50 relative group/q animate-in slide-in-from-top-4"><button type="button" onClick={() => handleRemoveQuestion(qIndex)} className="absolute -top-2 -right-2 p-2 bg-red-500 text-white rounded-full opacity-0 group-hover/q:opacity-100 transition-opacity"><Trash2 size={14} /></button><div className="space-y-6"><div className="flex gap-4"><span className="h-10 w-10 bg-indigo-600/20 text-indigo-400 border border-indigo-600/30 rounded-xl flex items-center justify-center font-bold text-sm shrink-0">{qIndex + 1}</span><input required value={q.text} onChange={e => { const newQuestions = [...examForm.questions]; newQuestions[qIndex].text = e.target.value; setExamForm({...examForm, questions: newQuestions}); }} placeholder="Enunciado da questão..." className="flex-1 bg-transparent border-b border-slate-700 focus:border-indigo-500 outline-none text-white py-2" /></div><div className="grid grid-cols-1 md:grid-cols-2 gap-4 pl-14">{q.options.map((opt, oIndex) => (<div key={oIndex} className={`flex items-center gap-3 p-3 rounded-2xl border transition-all ${q.correctOptionIndex === oIndex ? 'bg-emerald-500/10 border-emerald-500/50 shadow-lg' : 'bg-slate-900/50 border-slate-700/50'}`}><button type="button" onClick={() => { const newQuestions = [...examForm.questions]; newQuestions[qIndex].correctOptionIndex = oIndex; setExamForm({...examForm, questions: newQuestions}); }} className={`h-5 w-5 rounded-full border-2 flex items-center justify-center ${q.correctOptionIndex === oIndex ? 'bg-emerald-500 border-emerald-500 text-white' : 'border-slate-600'}`}>{q.correctOptionIndex === oIndex && <CheckCircle size={14} />}</button><input required value={opt} onChange={e => { const newQuestions = [...examForm.questions]; newQuestions[qIndex].options[oIndex] = e.target.value; setExamForm({...examForm, questions: newQuestions}); }} placeholder={`Alternativa ${String.fromCharCode(65 + oIndex)}`} className="bg-transparent text-xs text-white outline-none flex-1" /></div>))}</div></div></div>))}</div>
              </div>
              <footer className="pt-8 flex gap-4"><button type="button" onClick={() => setIsExamModalOpen(false)} className="flex-1 px-8 py-5 border border-slate-700 text-slate-400 rounded-2xl font-bold uppercase tracking-widest hover:bg-slate-800 transition-all">Cancelar</button><button type="submit" className="flex-[2] px-8 py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl hover:bg-indigo-500 transition-all active:scale-95">Salvar Avaliação</button></footer>
            </form>
          </div>
        </div>
      )}

      {/* MODALS EXISTENTES */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6 border border-slate-100"><h3 className="font-bold text-slate-900 mb-4">{currentEditingModule ? 'Editar Módulo' : 'Configurar Novo Módulo'}</h3><form onSubmit={handleSaveModule} className="space-y-5"><div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Título</label><input required autoFocus value={moduleForm.nome} onChange={e => setModuleForm({...moduleForm, nome: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div><div className="flex gap-3"><button type="button" onClick={() => setIsModuleModalOpen(false)} className="flex-1 px-4 py-2.5 border rounded-xl font-bold text-sm">Cancelar</button><button type="submit" className="flex-1 bg-indigo-600 text-white py-2.5 rounded-xl font-bold text-sm shadow-lg">Salvar</button></div></form></div>
        </div>
      )}

      {showLessonModal && (
        <div className="fixed inset-0 !z-[9998] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white w-full max-w-xl rounded-3xl shadow-2xl p-8 border border-slate-100 animate-in zoom-in-95">
            <h3 className="font-bold text-slate-900 text-xl mb-6 flex items-center gap-3"><PlusCircle size={24} className="text-indigo-600" /> {isEditingLesson ? 'Editar Aula' : 'Publicar Nova Unidade'}</h3>
            <form onSubmit={handleSaveLesson} className="space-y-5">
              <input required value={lessonForm.titulo} onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})} placeholder="Título da Aula" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
              <textarea value={lessonForm.descricao} onChange={e => setLessonForm({...lessonForm, descricao: e.target.value})} placeholder="Descrição pedagógica..." className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm resize-none" rows={4}></textarea>
              <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Vídeo (YouTube)</label><input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="https://youtube.com/watch?v=..." className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div>
              <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Material de Apoio (Link)</label><div className="flex gap-2"><input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="URL do arquivo..." className="flex-1 px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" /><button type="button" onClick={() => handleOpenMaterialPicker('document', (url) => setLessonForm(prev => ({...prev, materialUrl: url})))} className="px-4 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 transition-all shadow-lg flex items-center gap-2"><Library size={18} /></button></div></div>
              <div className="flex gap-4 pt-4"><button type="button" onClick={() => setShowLessonModal(false)} className="flex-1 py-4 border border-slate-200 text-slate-500 rounded-2xl font-bold text-sm">Cancelar</button><button type="submit" className="flex-[2] bg-slate-900 text-white py-4 rounded-2xl font-bold text-sm shadow-xl active:scale-95">Salvar Alterações</button></div>
            </form>
          </div>
        </div>
      )}

      {showCourseModal && (
        <div className="fixed inset-0 !z-[9997] flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-slate-900 w-full max-w-4xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 flex flex-col max-h-[90vh] border border-slate-800">
            <div className="p-8 pb-0 border-b border-slate-800 flex flex-col gap-6">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-4"><div className="bg-indigo-600 p-3 rounded-2xl text-white shadow-xl shadow-indigo-900/20"><GraduationCap size={28} /></div><div><h3 className="font-bold text-white text-2xl tracking-tight">{isEditingCourse ? 'Refinar Matriz Acadêmica' : 'Projetar Novo Curso'}</h3><p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.2em] mt-1">Configurações Avançadas</p></div></div>
                <button onClick={handleCloseCourseModal} className="text-slate-500 hover:text-white p-2 transition-colors"><X size={32} /></button>
              </div>
              <div className="flex gap-1 pb-4">
                {[{ id: 'geral', label: 'Dados Gerais', icon: <Info size={16} /> }, { id: 'docente', label: 'Corpo Docente', icon: <UserCheck size={16} /> }, { id: 'midia', label: 'Mídias', icon: <Clapperboard size={16} /> }].map((tab) => (
                  <button key={tab.id} type="button" onClick={() => setActiveModalTab(tab.id as any)} className={`flex items-center gap-2 px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeModalTab === tab.id ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-800 hover:text-slate-300'}`}>{tab.icon}{tab.label}</button>
                ))}
              </div>
            </div>
            <form onSubmit={handleSaveCourse} className="flex-1 overflow-y-auto p-10 pt-8 space-y-8">
              {activeModalTab === 'geral' && (
                <div className="space-y-8 animate-in slide-in-from-left-4">
                  <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Título do Curso</label><input required value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Ex: Teologia do NT" className="w-full px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-sm text-white focus:ring-2 focus:ring-indigo-500 outline-none" /></div>
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Tema</label><input value={courseForm.tema} onChange={e => setCourseForm({...courseForm, tema: e.target.value})} className="w-full px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-sm text-white focus:ring-2 focus:ring-indigo-500 outline-none" /></div>
                  </div>
                  <div className="grid grid-cols-3 gap-6">
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Categoria</label><select required value={courseForm.categoria} onChange={e => setCourseForm({...courseForm, categoria: e.target.value})} className="w-full px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-sm text-white outline-none"><option value="Teologia">Teologia</option><option value="Liderança">Liderança</option><option value="Missões">Missões</option></select></div>
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Nível</label><select required value={courseForm.nivelDificuldade} onChange={e => setCourseForm({...courseForm, nivelDificuldade: e.target.value as any})} className="w-full px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-sm text-white outline-none"><option value="Iniciante">Iniciante</option><option value="Intermediário">Intermediário</option><option value="Avançado">Avançado</option></select></div>
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Carga Horária</label><input required value={courseForm.cargaHoraria} onChange={e => setCourseForm({...courseForm, cargaHoraria: e.target.value})} className="w-full px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-sm text-white outline-none" /></div>
                  </div>
                  <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Ementa</label><textarea required value={courseForm.descricaoLonga} onChange={e => setCourseForm({...courseForm, descricaoLonga: e.target.value})} className="w-full px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-sm text-white outline-none min-h-[120px] resize-none"></textarea></div>
                </div>
              )}
              {activeModalTab === 'docente' && (
                <div className="space-y-8 animate-in slide-in-from-left-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Professor</label><input required value={courseForm.professorResponsavel} onChange={e => setCourseForm({...courseForm, professorResponsavel: e.target.value})} className="w-full px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-sm text-white outline-none" /></div>
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Foto URL</label><div className="flex gap-2"><input value={courseForm.professorPhotoURL} onChange={e => setCourseForm({...courseForm, professorPhotoURL: e.target.value})} className="flex-1 px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-sm text-white outline-none" /><button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm(prev => ({...prev, professorPhotoURL: url})))} className="px-4 bg-indigo-600 text-white rounded-2xl"><Library size={20} /></button></div></div>
                  </div>
                </div>
              )}
              {activeModalTab === 'midia' && (
                <div className="space-y-8 animate-in slide-in-from-left-4">
                  <div className="space-y-4">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Capa (Imagem Principal)</label>
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
                      <div className="lg:col-span-2 space-y-4">
                        <div className="flex gap-2"><input required value={courseForm.capaUrl} onChange={e => setCourseForm({...courseForm, capaUrl: e.target.value})} className="flex-1 px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-sm text-white outline-none" /><button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm(prev => ({...prev, capaUrl: url})))} className="px-4 bg-indigo-600 text-white rounded-2xl shadow-lg transition-all"><Library size={20} /></button></div>
                      </div>
                      <div className="aspect-video bg-slate-800 rounded-3xl border border-slate-700 overflow-hidden relative shadow-2xl">
                        {courseForm.capaUrl ? <img src={courseForm.capaUrl} className="w-full h-full object-cover" /> : <div className="flex flex-col items-center gap-2 opacity-20"><Clapperboard size={48} /><span className="text-[9px] font-black uppercase">Preview</span></div>}
                      </div>
                    </div>
                  </div>
                </div>
              )}
              <footer className="pt-8 flex gap-4 border-t border-slate-800 sticky bottom-0 bg-slate-900 mt-auto">
                <button type="button" onClick={handleCloseCourseModal} className="flex-1 py-5 border border-slate-700 text-slate-400 rounded-2xl font-bold uppercase text-xs tracking-[0.2em] hover:bg-slate-800 transition-all">Descartar</button>
                <button type="submit" disabled={loading} className="flex-[2] bg-indigo-600 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-2xl shadow-indigo-900/40 hover:bg-indigo-500 transition-all active:scale-95 disabled:opacity-50">
                  {loading ? 'Salvando...' : (isEditingCourse ? 'Atualizar Matriz' : 'Publicar Matriz')}
                </button>
              </footer>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;
